<div class="page-heading"><div><span class="eyebrow">Hospital · Vaccine status</span><h1>Availability &amp; stock</h1><p>Parents and administrators see these available or unavailable values immediately.</p></div></div>
<form method="post" action="<?= e(url('hospital.inventory.update')) ?>" data-inventory-form><?= csrf_field() ?><section class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow"><?= count($vaccines) ?> scheduled doses</span><h2>Vaccine list</h2></div><button class="button" type="submit">Save vaccine status</button></div><div class="table-scroll"><table class="inventory-table"><thead><tr><th>Vaccine</th><th>Schedule</th><th>Stock quantity</th><th>Available</th></tr></thead><tbody><?php foreach ($vaccines as $vaccine): ?><tr><td><strong><?= e($vaccine['name']) ?></strong><small><?= e($vaccine['disease']) ?></small></td><td><?= e($vaccine['dose_label']) ?><small><?= (int) $vaccine['recommended_age_months'] === 0 ? 'At birth' : (int) $vaccine['recommended_age_months'] . ' months' ?></small></td><td><input class="stock-input" type="number" name="stock[<?= (int) $vaccine['id'] ?>]" value="<?= (int) $vaccine['stock_quantity'] ?>" min="0" max="100000" inputmode="numeric" aria-label="<?= e($vaccine['name'] . ' ' . $vaccine['dose_label']) ?> stock"></td><td><label class="switch"><input type="checkbox" name="available[<?= (int) $vaccine['id'] ?>]" value="1" <?= $vaccine['is_available'] && $vaccine['stock_quantity'] > 0 ? 'checked' : '' ?>><span></span><em><?= $vaccine['is_available'] && $vaccine['stock_quantity'] > 0 ? 'Available' : 'Unavailable' ?></em></label></td></tr><?php endforeach; ?></tbody></table></div><div class="panel-foot"><p>Availability automatically turns off when stock reaches zero.</p><button class="button" type="submit">Save vaccine status</button></div></section></form>
